SELECT p.gender, a.admission_type, d.diagnosis_code, d.diagnosis_date, COUNT(p.subject_id) AS procedure_count, AVG(p.value) AS avg_procedure_value, MIN(p.value) AS min_procedure_value, MAX(p.value) AS max_procedure_value FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id AND a.hadm_id = d.hadm_id WHERE p.gender = 'F' AND EXTRACT(YEAR FROM d.diagnosis_date) BETWEEN 2015 AND 2016 AND d.diagnosis_code = 'I60.9' AND a.discharge_location = '657071' AND a.discharge_disposition = 'A' AND (a.dischtime - a.admittime) BETWEEN 1 AND 8 AND (a.dischtime - a.admittime) / NULLIF(a.length_of_stay, 0) BETWEEN 1 AND 4 AND d.diagnosis_date BETWEEN (a.admittime + interval '1 day') AND (a.dischtime - interval '1 day') AND p.anchor_age BETWEEN 59 AND 65 AND p.anchor_year BETWEEN 2015 AND 2016 AND p.anchor_year_group = '50-59' GROUP BY p.gender, a.admission_type, d.diagnosis_code, d.diagnosis_date ORDER BY p.gender, a.admission_type, d.diagnosis_code, d.diagnosis_date NULLS LAST;